style.css:
@-moz-document domain("roblox.com") {
@media (prefers-color-scheme: dark) {

/* ===== COLOR SYSTEM ===== */
:root {
    -bg-main: #030000;
    -bg-secondary: #0a0000;
    -red-primary: #ff0000;
    -red-deep: #8b0000;
    -red-glow: rgba(255, 0, 0, 0.9);
    -text-main: #f0f0f0;
    -text-muted: #9a9a9a;
}

/* ===== GLOBAL DARK BACKGROUND ===== */
body {
    background-color: var(--bg-main) !important;
    background-image:
        url("https://i.imgur.com/8ZQZQZy.png"),
        radial-gradient(circle at center, #160000 0%, #030000 70%);
    background-repeat: repeat;
    background-size: 600px;
    background-attachment: fixed;
    color: var(--text-main) !important;
    font-family: "Inter", "Segoe UI", sans-serif;
}

/* ===== RED SIGIL ATMOSPHERE ===== */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: radial-gradient(circle at center,
        rgba(255, 0, 0, 0.15),
        transparent 60%);
    pointer-events: none;
    z-index: 0;
}

/* ===== NAVBAR ===== */
.navbar,
.rbx-header {
    background: linear-gradient(180deg, #120000, #050000) !important;
    border-bottom: 2px solid var(--red-primary);
    box-shadow:
        0 0 30px var(--red-glow),
        inset 0 -2px 12px rgba(255, 0, 0, 0.5);
}

/* ===== LINKS ===== */
a {
    color: var(--red-primary) !important;
    text-shadow: 0 0 8px var(--red-glow);
}

a:hover {
    color: #ffffff !important;
    text-shadow: 0 0 18px var(--red-primary);
}

/* ===== BUTTONS ===== */
.btn,
button {
    background: linear-gradient(180deg, #100000, #050000) !important;
    color: var(--text-main) !important;
    border: 1px solid var(--red-primary) !important;
    box-shadow:
        inset 0 0 10px rgba(255, 0, 0, 0.6),
        0 0 12px var(--red-glow);
}

.btn:hover,
button:hover {
    background: var(--red-primary) !important;
    color: #000 !important;
    box-shadow:
        0 0 35px var(--red-glow),
        0 0 55px rgba(255, 0, 0, 0.8);
}

/* ===== PANELS / CARDS ===== */
.section-content,
.container-header,
.item-card {
    position: relative;
    background-color: var(--bg-secondary) !important;
    border: 1px solid rgba(255, 0, 0, 0.4);
    box-shadow:
        inset 0 0 22px rgba(255, 0, 0, 0.4),
        0 0 20px rgba(255, 0, 0, 0.25);
}

/* ===== PANEL SIGIL OVERLAY ===== */
.section-content::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: url("https://i.imgur.com/5xF7N3Q.png");
    background-size: 420px;
    opacity: 0.09;
    pointer-events: none;
}

/* ===== HEADINGS ===== */
h1, h2, h3, h4 {
    color: #ff1c1c !important;
    text-shadow:
        0 0 12px var(--red-glow),
        0 0 30px rgba(255, 0, 0, 0.7);
}

/* ===== INPUTS ===== */
input,
textarea,
select {
    background-color: #020000 !important;
    color: var(--text-main) !important;
    border: 1px solid var(--red-primary) !important;
    box-shadow: inset 0 0 12px rgba(255, 0, 0, 0.7);
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-track {
    background: #020000;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #ff0000, #5a0000);
    box-shadow: 0 0 18px var(--red-glow);
}

/* ===== FORCE DARK (REMOVE LIGHT ELEMENTS) ===== */
[class*="light-theme"],
[class*="theme-light"],
[class*="rbx-light"] {
    background: transparent !important;
    color: var(--text-main) !important;
}

}
}
